def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(text, encoding="utf-8")
    print(text, end="")
    return exit_code


def import_pybamm():
    os.environ.setdefault("PYBAMM_DISABLE_TELEMETRY", "true")
    if str(SOURCE_SRC) not in sys.path:
        sys.path.insert(0, str(SOURCE_SRC))
    import pybamm  # type: ignore

    return pybamm


def build_parameter_values(pybamm, parameter_set: str):
    module = import_module(f"pybamm.input.parameters.lithium_ion.{parameter_set}")
    params = pybamm.ParameterValues(module.get_parameter_values())
    if parameter_set == "Xu2019":
        params.update(PUBLIC_PARAMETER_OVERRIDES, check_already_exists=False)
    return params


def boundary_condition_for_symbol(model, symbol_type, *fragments: str):
    for key, bc_map in model.boundary_conditions.items():
        if isinstance(key, symbol_type) and all(
            fragment in str(key) for fragment in fragments
        ):
            return bc_map
    raise AssertionError(
        f"missing boundary conditions for {symbol_type.__name__} matching {fragments!r}"
    )


def boundary_signature(pybamm, model):
    surface_potential = boundary_condition_for_symbol(
        model,
        pybamm.Concatenation,
        "Lithium metal interface surface potential difference [V]",
        "Positive electrode surface potential difference [V]",
    )
    electrolyte_concentration = boundary_condition_for_symbol(
        model,
        pybamm.Concatenation,
        "Separator porosity times concentration [mol.m-3]",
        "Positive electrode porosity times concentration [mol.m-3]",
    )
    return {
        "boundary_condition_count": len(model.boundary_conditions),
        "surface_potential_boundary": {
            "left": surface_potential["left"][1],
            "right": surface_potential["right"][1],
        },
        "electrolyte_concentration_boundary": {
            "left": electrolyte_concentration["left"][1],
            "right": electrolyte_concentration["right"][1],
        },
    }


def run_scenario(pybamm, scenario: dict[str, object]) -> dict[str, object]:
    params = build_parameter_values(pybamm, scenario["parameter_set"])
    model_cls = getattr(pybamm.lithium_ion, scenario["model"])
    model = model_cls(dict(scenario["options"]))
    sim = pybamm.Simulation(model, parameter_values=params, C_rate=scenario["c_rate"])
    sim.build()
    built_model = sim._model
    solution = sim.solve(scenario["t_eval"])
    times = np.linspace(scenario["t_eval"][0], scenario["t_eval"][-1], 5)
    voltage = np.asarray(solution["Voltage [V]"](times), dtype=float)
    temperature = np.asarray(
        solution["Volume-averaged cell temperature [K]"](times), dtype=float
    )
    ohmic_heating = np.asarray(
        solution["Volume-averaged Ohmic heating [W.m-3]"](times), dtype=float
    )
    result = {
        "status": "ok",
        "model": scenario["model"],
        "t_eval": list(scenario["t_eval"]),
        "c_rate": scenario["c_rate"],
        "initial_voltage": float(voltage[0]),
        "final_voltage": float(voltage[-1]),
        "voltage_drop": float(voltage[0] - voltage[-1]),
        "initial_temperature": float(temperature[0]),
        "final_temperature": float(temperature[-1]),
        "max_temperature": float(np.max(temperature)),
        "final_ohmic_heating": float(ohmic_heating[-1]),
        "max_ohmic_heating": float(np.max(ohmic_heating)),
        "finite": bool(
            np.all(np.isfinite(voltage))
            and np.all(np.isfinite(temperature))
            and np.all(np.isfinite(ohmic_heating))
        ),
        "points": int(voltage.size),
    }
    if (
        scenario["options"].get("working electrode") == "positive"
        and scenario["options"].get("surface form") == "differential"
        and scenario["options"].get("thermal") == "lumped"
    ):
        result["boundary_signature"] = boundary_signature(pybamm, built_model)
    return result


def main() -> int:
    try:
        pybamm = import_pybamm()
    except Exception as exc:  # noqa: BLE001 - import/runtime setup failure.
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    scenario_results: list[dict[str, object]] = []
    overall_status = "workflow_completed"

    for scenario in SCENARIOS:
        try:
            result = run_scenario(pybamm, scenario)
        except Exception as exc:  # noqa: BLE001 - scenario failure is reported.
            result = {
                "status": "failed",
                "error_type": type(exc).__name__,
                "error": str(exc),
            }
            overall_status = "pre_fix_expected_failure"
        scenario_results.append({"name": scenario["name"], **result})

    if overall_status == "workflow_completed":
        successful = {
            item["name"]: item for item in scenario_results if item["status"] == "ok"
        }
        final_voltages = [
            item["final_voltage"]
            for item in scenario_results
            if item["status"] == "ok" and "final_voltage" in item
        ]
        case_01 = successful["case_01"]
        case_02 = successful["case_02"]
        case_03 = successful["case_03"]
        return write_report(
            {
                "schema_version": "1.0",
                "status": "workflow_completed",
                "scenarios": scenario_results,
                "observation": {
                    "completed_workflows": len(scenario_results),
                    "final_voltage_min": min(final_voltages),
                    "final_voltage_max": max(final_voltages),
                    "surface_form_consistency": {
                        "final_voltage_gap": abs(
                            case_01["final_voltage"] - case_02["final_voltage"]
                        ),
                        "final_temperature_gap": abs(
                            case_01["final_temperature"] - case_02["final_temperature"]
                        ),
                    },
                    "thermal_signature": {
                        "temperature_rise": case_03["max_temperature"]
                        - case_03["initial_temperature"],
                        "peak_ohmic_heating": case_03["max_ohmic_heating"],
                        "boundary_condition_count": case_03["boundary_signature"][
                            "boundary_condition_count"
                        ],
                        "surface_potential_boundary": case_03["boundary_signature"][
                            "surface_potential_boundary"
                        ],
                    },
                },
            },
            0,
        )

    failed = [item for item in scenario_results if item["status"] != "ok"]
    return write_report(
        {
            "schema_version": "1.0",
            "status": "pre_fix_expected_failure",
            "scenarios": scenario_results,
            "observation": {
                "completed_workflows": len(scenario_results) - len(failed),
                "failed_workflows": [
                    {"name": item["name"], "error_type": item.get("error_type")}
                    for item in failed
                ],
            },
        },
        1,
    )


if __name__ == "__main__":
